import React, { useState, useRef } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, 
  Search, Filter, AlertCircle, ChevronLeft, ChevronRight 
} from 'lucide-react';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('BINS');
  const scrollRef = useRef(null);

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={20}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={20}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={20}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={20}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={20}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={20}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={20}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={20}/> },
  ];

  // Logic to slide the "Internal Screen" when a button is clicked
  const scrollToTab = (tabId, index) => {
    setActiveTab(tabId);
    if (scrollRef.current) {
      const screenWidth = scrollRef.current.offsetWidth;
      scrollRef.current.scrollTo({
        left: screenWidth * index,
        behavior: 'smooth'
      });
    }
  };

  // Sync the Active Tab state if the user manually swipes the screen
  const handleInternalScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / scrollRef.current.offsetWidth);
      if (allTabs[index] && allTabs[index].id !== activeTab) {
        setActiveTab(allTabs[index].id);
      }
    }
  };

  return (
    <div className="w-full h-screen max-h-screen overflow-hidden bg-[#FDFAD8] p-4 md:p-6 flex flex-center justify-center">

      {/* THE MAIN CHASSIS: Adapts to screen but keeps a fixed "Instrument" feel */}
      <div className="w-full max-w-[1400px] h-full flex flex-col gap-4 mx-auto">

        {/* BLOCK 1: BRANDED HEADER (Fixed) */}
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] rounded-b-[12px] p-5 shrink-0 red-stack-shadow">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="bg-[#FDFAD8] p-2 rounded-xl border-4 border-[#47510B] shadow-[3px_3px_0_0_#47510B]">
                <ShieldAlert size={28} className="text-[#AB1717]" strokeWidth={2.5} />
              </div>
              <h1 className="text-2xl md:text-3xl font-black italic text-[#FDFAD8] uppercase tracking-tighter">
                TRASH<span className="text-[#CAD23C]">2</span>TRACK
              </h1>
            </div>
            <Activity className="text-[#CAD23C] animate-pulse" size={24} />
          </div>
        </div>

        {/* BLOCK 2: THE SELECTOR TRAY (Fixed) */}
        <div className="bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[20px] p-3 shrink-0 yellow-stack-shadow">
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar px-2">
            {allTabs.map((tab, index) => (
              <button
                key={tab.id}
                onClick={() => scrollToTab(tab.id, index)}
                className={`
                  flex-shrink-0 flex items-center gap-3 px-6 py-4 rounded-[18px] border-[4px] border-[#47510B] font-black text-[10px] uppercase transition-all
                  ${activeTab === tab.id 
                    ? 'bg-[#CAD23C] text-[#47510B] shadow-none translate-y-1' 
                    : 'bg-[#FDFAD8] text-[#AB1717] shadow-[4px_4px_0_0_#47510B] hover:translate-y-0.5'}
                `}
              >
                {tab.icon}
                <span className="whitespace-nowrap">{tab.label}</span>
              </button>
            ))}
          </div>
        </div>

        <p className="text-center text-[9px] font-black uppercase tracking-[0.8em] text-[#AB1717] opacity-60 shrink-0 mb-2">
          Secure.Terminal.Trash2Track.V3.2026
        </p>
      </div>
    </div>
  );
};

export default Dashboard;
